// ── Shared helpers used by every page ───────────────────────────────────────

// Escape user-provided text before putting it into innerHTML (titles, addresses, names, ...).
function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// URL of an uploaded photo (file names are generated by the server, but encode anyway).
function photoUrl(name) { return '/uploads/' + encodeURIComponent(name); }

function parseImages(json) {
  try { const a = JSON.parse(json || '[]'); return Array.isArray(a) ? a : []; } catch { return []; }
}

function requireAuth() {
  if (!localStorage.getItem('dr_token')) { location.href = '/'; return null; }
}

function getUser() {
  try { return JSON.parse(localStorage.getItem('dr_user')); } catch { return null; }
}

function logout() {
  localStorage.removeItem('dr_token');
  localStorage.removeItem('dr_user');
  location.href = '/';
}

// ── Sidebar (one definition for all pages) ──────────────────────────────────
const LOGO_SVG = `<svg viewBox="0 0 40 40" fill="none"><rect width="40" height="40" rx="10" fill="#0D2137"/><rect x="1" y="1" width="38" height="38" rx="9" stroke="#C8A951" stroke-width="1" fill="none" opacity="0.4"/><rect x="26" y="6" width="5" height="11" rx="0.5" fill="#C8A951"/><path d="M20 5L1 19L39 19Z" fill="#C8A951" fill-opacity="0.12"/><polyline points="1,19 20,5 39,19" stroke="#C8A951" stroke-width="2" stroke-linejoin="round" fill="none"/><rect x="3" y="19" width="34" height="16" fill="none" stroke="#C8A951" stroke-width="1.5"/><rect x="5" y="21" width="8" height="5" rx="0.5" fill="none" stroke="#C8A951" stroke-width="1.2"/><rect x="27" y="21" width="8" height="5" rx="0.5" fill="none" stroke="#C8A951" stroke-width="1.2"/><rect x="15" y="26" width="10" height="9" rx="1" fill="#C8A951"/></svg>`;

const NAV_ITEMS = [
  { label: 'Головне' },
  { page: 'dashboard',  href: 'dashboard.html',                 icon: 'fa-chart-pie', text: 'Дашборд' },
  { label: 'Нерухомість' },
  { page: 'apartments', href: 'properties.html?type=apartment', icon: 'fa-building',  text: 'Квартири' },
  { page: 'houses',     href: 'properties.html?type=house',     icon: 'fa-home',      text: 'Будинки' },
  { page: 'land',       href: 'properties.html?type=land',      icon: 'fa-tree',      text: 'Ділянки' },
  { page: 'properties', href: 'properties.html',                icon: 'fa-list',      text: "Всі об'єкти" },
  { label: 'Адміністрування', admin: true },
  { page: 'employees',  href: 'employees.html',                 icon: 'fa-users',     text: 'Співробітники', admin: true },
];

function currentNavPage() {
  const file = location.pathname.split('/').pop() || 'index.html';
  if (file === 'dashboard.html') return 'dashboard';
  if (file === 'employees.html') return 'employees';
  if (file === 'properties.html') {
    const t = new URLSearchParams(location.search).get('type');
    return { apartment: 'apartments', house: 'houses', land: 'land' }[t] || 'properties';
  }
  if (file === 'property-form.html') return 'properties';
  return '';
}

function buildSidebar() {
  const side = document.querySelector('.sidebar');
  if (!side || side.dataset.built) return;
  side.dataset.built = '1';
  const active = currentNavPage();
  side.innerHTML = `
    <a class="sidebar-logo" href="dashboard.html">
      ${LOGO_SVG}
      <div class="brand-text"><div class="name"><span>DIM</span> REALTY</div><div class="sub">Admin Panel</div></div>
    </a>
    <nav class="sidebar-nav">
      ${NAV_ITEMS.map(n => n.label
        ? `<div class="nav-section-label${n.admin ? ' admin-only' : ''}">${n.label}</div>`
        : `<a href="${n.href}" class="nav-item${n.admin ? ' admin-only' : ''}${n.page === active ? ' active' : ''}" data-page="${n.page}"><i class="fas ${n.icon}"></i><span>${n.text}</span></a>`
      ).join('')}
    </nav>
    <div class="sidebar-user">
      <div class="user-avatar-sm" id="sidebar-avatar"></div>
      <div class="sidebar-user-info">
        <div class="uname" id="sidebar-user-name">Завантаження...</div>
        <div class="urole" id="sidebar-user-role"></div>
      </div>
      <button class="sidebar-logout" onclick="logout()" title="Вийти"><i class="fas fa-sign-out-alt"></i></button>
    </div>`;
  if (!document.querySelector('.sidebar-backdrop')) {
    const bd = document.createElement('div');
    bd.className = 'sidebar-backdrop';
    bd.onclick = () => setSidebar(false);
    document.body.appendChild(bd);
  }
}

function renderSidebarUser() {
  buildSidebar();
  const user = getUser();
  if (!user) return;
  const el = document.getElementById('sidebar-user-name');
  const rl = document.getElementById('sidebar-user-role');
  const av = document.getElementById('sidebar-avatar');
  if (el) el.textContent = user.name;
  if (rl) rl.textContent = user.role === 'admin' ? 'Адміністратор' : 'Агент';
  if (av) {
    if (user.avatar) av.innerHTML = `<img src="${photoUrl(user.avatar)}" alt="">`;
    else av.textContent = (user.name || '?').charAt(0).toUpperCase();
  }
  // Hide admin-only elements if not admin
  if (user.role !== 'admin') {
    document.querySelectorAll('.admin-only').forEach(el => el.style.display = 'none');
  }
  // Make sidebar user block clickable → profile edit
  const sidebarUser = document.querySelector('.sidebar-user');
  if (sidebarUser) {
    sidebarUser.title = 'Редагувати профіль';
    sidebarUser.addEventListener('click', e => {
      if (e.target.closest('.sidebar-logout')) return; // don't open on logout click
      openProfileModal();
    });
  }
  // Inject profile modal once
  if (!document.getElementById('profile-modal')) {
    const m = document.createElement('div');
    m.id = 'profile-modal';
    m.className = 'modal-overlay';
    m.innerHTML = `
      <div class="modal" style="max-width:460px">
        <div class="modal-header">
          <span class="modal-title"><i class="fas fa-user-edit" style="color:var(--gold);margin-right:8px"></i>Мій профіль</span>
          <button class="modal-close" onclick="document.getElementById('profile-modal').classList.remove('open')">×</button>
        </div>
        <div class="modal-body">
          <form id="profile-form" onsubmit="saveProfile(event)">
            <div class="form-grid" style="gap:16px">
              <div class="form-group full">
                <label class="form-label">Повне ім'я *</label>
                <input class="form-control" id="prof-name" required placeholder="Іван Іваненко">
              </div>
              <div class="form-group full">
                <label class="form-label">Телефон</label>
                <input class="form-control" id="prof-phone" type="tel" placeholder="+380 XX XXX XX XX">
              </div>
              <div class="form-group full" style="border-top:1px solid var(--border);padding-top:16px;margin-top:4px">
                <label class="form-label">Новий пароль</label>
                <input class="form-control" id="prof-password" type="password" minlength="6" autocomplete="new-password" placeholder="Залиште порожнім — не зміниться">
              </div>
            </div>
          </form>
        </div>
        <div class="modal-footer">
          <button class="btn btn-outline" onclick="document.getElementById('profile-modal').classList.remove('open')">Скасувати</button>
          <button class="btn btn-primary" id="prof-save-btn" onclick="document.getElementById('profile-form').requestSubmit()">
            <i class="fas fa-save"></i> Зберегти
          </button>
        </div>
      </div>`;
    document.body.appendChild(m);
  }
}

function openProfileModal() {
  const user = getUser();
  if (!user) return;
  document.getElementById('prof-name').value     = user.name  || '';
  document.getElementById('prof-phone').value    = user.phone || '';
  document.getElementById('prof-password').value = '';
  document.getElementById('profile-modal').classList.add('open');
}

async function saveProfile(e) {
  e.preventDefault();
  const btn = document.getElementById('prof-save-btn');
  btn.disabled = true;
  const body = {
    name:     document.getElementById('prof-name').value,
    phone:    document.getElementById('prof-phone').value,
    password: document.getElementById('prof-password').value || undefined,
  };
  try {
    await api.put('/auth/me', body);
    // Update local user cache
    const user = getUser();
    if (user) {
      user.name  = body.name;
      user.phone = body.phone;
      localStorage.setItem('dr_user', JSON.stringify(user));
    }
    document.getElementById('profile-modal').classList.remove('open');
    // Refresh sidebar name
    const nameEl = document.getElementById('sidebar-user-name');
    if (nameEl) nameEl.textContent = body.name;
    const avEl = document.getElementById('sidebar-avatar');
    if (avEl && !user?.avatar) avEl.textContent = body.name.charAt(0).toUpperCase();
    toast('Профіль оновлено', 'success');
  } catch(ex) {
    toast(ex.message || 'Помилка збереження', 'error');
  } finally {
    btn.disabled = false;
  }
}

// Formatted price
function fmtPrice(n) {
  if (n === null || n === undefined || n === '') return '—';
  return '$' + Math.round(Number(n)).toLocaleString('uk-UA');
}

function fmtArea(n, type) {
  if (!n) return '—';
  if (type === 'land') {
    const hectares = (n / 10000).toFixed(2);
    const sotky = Math.round(n / 100);
    return `${n} м² (${sotky} соток) / ${hectares} га`;
  }
  return `${n} м²`;
}

// Property type labels
const TYPE_LABELS = { apartment: 'Квартира', house: 'Будинок', land: 'Ділянка' };
const STATUS_LABELS = { available: 'Доступний', sold: 'Продано', reserved: 'Зарезервовано' };
const ROLE_LABELS = { admin: 'Адміністратор', agent: 'Агент' };

function typeBadge(type) {
  return `<span class="badge badge-${esc(type)}">${esc(TYPE_LABELS[type] || type)}</span>`;
}
function statusBadge(status) {
  return `<span class="badge badge-${esc(status)}">${esc(STATUS_LABELS[status] || status)}</span>`;
}

// Toast system (message is inserted as text, never as HTML)
const toastContainer = (() => {
  const d = document.createElement('div');
  d.className = 'toast-container';
  document.body.appendChild(d);
  return d;
})();

function toast(msg, type = 'success') {
  const icons = { success: 'fa-check-circle', error: 'fa-times-circle', warning: 'fa-exclamation-circle' };
  const t = document.createElement('div');
  t.className = `toast ${type}`;
  t.innerHTML = `<i class="fas ${icons[type] || icons.success}"></i><span class="toast-msg"></span><button class="toast-close" onclick="this.parentElement.remove()">×</button>`;
  t.querySelector('.toast-msg').textContent = msg;
  toastContainer.appendChild(t);
  setTimeout(() => t.remove(), type === 'error' ? 6000 : 3500);
}

// Format date
function fmtDate(str) {
  if (!str) return '—';
  const d = new Date(String(str).replace(' ', 'T') + (String(str).includes('Z') ? '' : 'Z'));   // SQLite stores UTC
  if (isNaN(d)) return '—';
  return d.toLocaleDateString('uk-UA', { day: '2-digit', month: '2-digit', year: 'numeric' });
}

// Sidebar mobile toggle (slides in over the page, dark backdrop closes it)
function setSidebar(open) {
  document.querySelector('.sidebar')?.classList.toggle('open', open);
  document.body.classList.toggle('sidebar-open', open);
}
function initSidebar() {
  buildSidebar();
  const toggle = document.getElementById('sidebar-toggle');
  if (toggle) toggle.addEventListener('click', () => setSidebar(!document.querySelector('.sidebar')?.classList.contains('open')));
  document.querySelector('.sidebar')?.addEventListener('click', e => { if (e.target.closest('.nav-item')) setSidebar(false); });
}

// Esc closes the topmost open dialog; clicking the dark area closes dialogs marked data-backdrop-close.
document.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  if (document.querySelector('.lightbox.open')) return;          // the photo viewer handles Esc itself
  const open = [...document.querySelectorAll('.modal-overlay.open')].pop();
  if (open) open.classList.remove('open');
  else setSidebar(false);
});
document.addEventListener('mousedown', e => {
  const o = e.target;
  if (o.classList?.contains('modal-overlay') && o.hasAttribute('data-backdrop-close')) o.classList.remove('open');
});
